import { Transition, Variant, Variants } from "framer-motion";

const transition = (duration: number) =>
  ({
    duration: duration,
    type: "spring",
  }) satisfies Transition;

const visibleVariant = (duration: number) =>
  ({
    x: 0,
    opacity: 1,
    transition: transition(duration),
  }) satisfies Variant;

export const slideLeftWhenHiddenVariants = (duration = 1) =>
  ({
    visible: visibleVariant(duration),
    hidden: {
      x: "-100%", //Slide to the left
      opacity: 0,
      transition: transition(duration),
    },
  }) satisfies Variants;

export const slideRightWhenHiddenVariants = (duration = 1) =>
  ({
    visible: visibleVariant(duration),
    hidden: {
      x: "100%", //Slide to the right
      opacity: 0,
      transition: transition(duration),
    },
  }) satisfies Variants;

/**
 * Fade + slide up when hidden. Used for swapping short pieces of text in/out (e.g. helper texts).
 * The `celebrate` variant adds a one-off scale pop for moments worth highlighting to the user.
 */
export const fadeUpWhenHiddenVariants = (duration = 0.3) =>
  ({
    visible: {
      y: 0,
      opacity: 1,
      transition: transition(duration),
    },
    hidden: {
      y: 8,
      opacity: 0,
      transition: transition(duration),
    },
    celebrate: {
      y: 0,
      opacity: 1,
      scale: [1, 1.06, 1],
      transition: transition(duration),
    },
  }) satisfies Variants;
