import { ComponentProps, useEffect, useState } from "react";
import { Meta, StoryObj } from "@storybook/react";
import { PurchaseMedia } from "./purchase-media";
import {
  CartResponseV2,
  CartResponseV2CartItem,
  CartState,
  CompanyShortName,
  DeliveryType,
  KlarnaPaymentResponse,
  Media,
  PaymentState,
  WebshopProductType,
} from "@parksandresorts/webapiproxy-types";
import { CheckoutService } from "@/core/services/checkout-service";
import { StaticConfigContextType } from "@/core/contexts";
import { PageProviders } from "@/core/providers";
import { allMedia, waitForVisibleElement } from "../../../digital-ride-media-storybook-helpers";
import { action } from "storybook/actions";
import { expect, waitFor, within } from "storybook/test";

const PHOTO_PRODUCT_GLK_ID = 123;
const VIDEO_PRODUCT_GLK_ID = 456;
const ALBUM_PRODUCT_GLK_ID = 789;
const ALBUM_UPGRADE_AFTER_ONE_MEDIA_GLK_ID = 901;
const ALBUM_UPGRADE_AFTER_TWO_MEDIA_GLK_ID = 902;

const PURCHASE_PRODUCT_GLK_IDS = {
  photo: PHOTO_PRODUCT_GLK_ID,
  video: VIDEO_PRODUCT_GLK_ID,
  album: ALBUM_PRODUCT_GLK_ID,
  albumUpgradeByMediaBought: {
    1: ALBUM_UPGRADE_AFTER_ONE_MEDIA_GLK_ID,
    2: ALBUM_UPGRADE_AFTER_TWO_MEDIA_GLK_ID,
  },
};

// Minimal GLK product mocks so useProduct() can resolve prices for the photo/video/album products.
const mockGlkProduct = (id: number, name: string, priceIncludingVat: number, ordinaryPrice?: number) => ({
  id,
  internalName: name,
  friendlySalesNameSwe: name,
  friendlyDisplayNameSwe: name,
  friendlySalesNameEng: name,
  friendlyDisplayNameEng: name,
  deliveryTypes: [{ deliveryType: DeliveryType.DIGITAL, deliveryProductId: undefined }],
  isBuyable: true,
  flags: {},
  minimumQuantity: 1,
  priceIncludingVat,
  priceExcludingVat: priceIncludingVat,
  vatAmount: 0,
  vatFraction: 0,
  productType: WebshopProductType.STANDARD,
  stockLevel: 1000,
  ordinaryPrice,
});

const mockStaticConfig: StaticConfigContextType = {
  eCommerce: {
    preferredPaymentProvider: "Klarna",
    shopServicePaymentSlug: "/payment",
    shopServiceConfirmationSlug: "/confirm",
    shopServiceCheckoutSlug: "/checkout",
  },
  products: {
    glkProducts: [
      mockGlkProduct(PHOTO_PRODUCT_GLK_ID, "Digital attraktionsbild", 60),
      mockGlkProduct(VIDEO_PRODUCT_GLK_ID, "Digital attraktionsvideo", 60),
      mockGlkProduct(ALBUM_PRODUCT_GLK_ID, "Attraktionsmedia album", 150),
      // 1 media bought (60 kr) → pay the remaining 90 kr up to the 150 kr album price.
      mockGlkProduct(ALBUM_UPGRADE_AFTER_ONE_MEDIA_GLK_ID, "Attraktionsmedia album", 90, 150),
      // 2 media bought (120 kr) → pay the remaining 30 kr up to the 150 kr album price.
      mockGlkProduct(ALBUM_UPGRADE_AFTER_TWO_MEDIA_GLK_ID, "Attraktionsmedia album", 30, 150),
    ],
    contentfulProducts: [],
  },
};

// A fake Klarna payment so the checkout widget below the cart renders a stable snippet instead of hitting a backend.
const klarnaPaymentResponse = (): KlarnaPaymentResponse => ({
  paymentProvider: "Klarna",
  cartGuid: "mock-cart-guid",
  paymentState: PaymentState.INITIALIZED,
  cartTotalAmount: 0,
  cartTotalVat: 0,
  vatAmounts: [],
  amountToPay: 0,
  giftCards: [],
  klarnaOrderId: "orderId",
  orderId: 123,
  htmlSnippet: `<div data-testid="klarna-html-snippet" style="padding: 16px; background: var(--foundation-color-primary-100);">Klarna checkout (mocked)</div>`,
});

// Mock of cart + payment backend so stories can render the whole purchase/checkout flow
let lastMockedCart: CartResponseV2 | undefined;
Object.assign(CheckoutService, {
  createCart: async (createCartRequest: { items: Array<{ productId: number; quantity?: number }> }) => {
    const cartItems = createCartRequest.items.map((item, index) => {
      const glkProduct = mockStaticConfig.products.glkProducts.find((product) => product.id === item.productId);
      const priceIncludingVat = glkProduct?.priceIncludingVat ?? 0;
      return {
        cartItemGuid: `mock-cart-item-${item.productId}-${index}`,
        productId: item.productId,
        productName: glkProduct?.friendlySalesNameSwe ?? "",
        quantity: item.quantity ?? 1,
        price: {
          amount: { amountIncludingVat: priceIncludingVat, vatAmount: 0 },
          vatPercentage: 0,
          unitPriceIncludingVat: priceIncludingVat,
        },
        deliveryType: DeliveryType.DIGITAL,
      } satisfies CartResponseV2CartItem;
    });
    lastMockedCart = {
      cartGuid: "mock-cart-guid",
      company: CompanyShortName.GLT,
      culture: "sv-SE",
      cartItems,
      cartPrice: {
        amount: {
          vatAmount: 0,
          amountIncludingVat: cartItems.reduce((sum, cartItem) => sum + cartItem.price.amount.amountIncludingVat, 0),
        },
      },
      timestamps: {
        createdOn: "2026-06-05T10:00:00",
        updatedOn: "2026-06-05T10:00:00",
        paymentInitializedOn: "2026-06-05T10:00:00",
        paymentCompletedOn: "2026-06-05T10:00:00",
        expiresOn: "2026-06-05T10:30:00",
      },
      discountItems: [],
      voucherCodes: [],
      redeemableValidationResults: [],
      state: CartState.OPEN,
    } satisfies CartResponseV2;
    return lastMockedCart;
  },
  getCart: async () => lastMockedCart,
  createKlarnaPaymentForCart: async (...params: unknown[]) => {
    action("createKlarnaPaymentForCart")(...params);
    return klarnaPaymentResponse();
  },
  getPaymentStatus: async (...params: unknown[]) => {
    action("getPaymentStatus")(...params);
    return klarnaPaymentResponse();
  },
  patchPaymentForCart: async (...params: unknown[]) => {
    action("patchPaymentForCart")(...params);
    return klarnaPaymentResponse();
  },
});

type StoryArgs = ComponentProps<typeof PurchaseMedia>;

const meta: Meta<StoryArgs> = {
  title: "Modules/Digital Ride Media/Purchase Media",
  component: PurchaseMedia,
  parameters: {
    chromatic: { delay: 2000 },
  },
  args: {
    albumId: "KOL-TOD-PUR-MED",
    confirmationPageSlug: "/confirmation",
    purchaseProductGlkIds: PURCHASE_PRODUCT_GLK_IDS,
    onBack: () => action("onBack")(),
  },
  render: function Render(args) {
    const [purchaseType, setPurchaseType] = useState(args.purchaseType);
    useEffect(() => setPurchaseType(args.purchaseType), [args.purchaseType]);
    return (
      <PageProviders
        currentContentPageData={{ slugs: { sv: "/", en: "/en" }, currentLocale: "sv" } as never}
        staticConfigData={mockStaticConfig}
      >
        <PurchaseMedia {...args} purchaseType={purchaseType} onSwitchToAlbumPurchase={() => setPurchaseType("album")} />
      </PageProviders>
    );
  },
};

export default meta;

type Story = StoryObj<typeof meta>;

const lockedPhotos: Array<Media> = [allMedia.createdToday, allMedia.createdTodayPortrait];

/** Buying the whole album up front (no media bought before), so the full album price is charged. */
export const AlbumPurchase: Story = {
  args: {
    purchaseType: "album",
    previouslyPurchasedMediaCount: 0,
    media: lockedPhotos,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await waitForVisibleElement({
      canvasElement,
      testId: "summary-total",
      assert: (el) => expect(el).toHaveTextContent("150 kr"),
    });
    await waitFor(() => expect(canvas.getByText("Obegränsat med bilder & videor från dagen! 🎉")).toBeVisible(), {
      timeout: 5000,
    });
  },
};

/** Buying a few individual media, with the banner nudging towards upgrading to the whole album. */
export const IndividualPurchase: Story = {
  args: {
    ...AlbumPurchase.args,
    purchaseType: "individual",
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await waitForVisibleElement({
      canvasElement,
      testId: "summary-total",
      assert: (el) => expect(el).toHaveTextContent("120 kr"),
    });
    await waitFor(() => expect(canvas.getByText("Obegränsat med bilder & videor från dagen?! 😮")).toBeVisible(), {
      timeout: 5000,
    });
    await waitForVisibleElement({
      canvasElement,
      testId: "ride-media-purchase-individual-media-banner-button",
    });
  },
};

/**
 * Upgrading to the album after having bought 1 media earlier. Only the remaining 90 kr is charged.
 */
export const AlbumUpgradeDiscount: Story = {
  args: {
    ...AlbumPurchase.args,
    previouslyPurchasedMediaCount: 1,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await waitForVisibleElement({
      canvasElement,
      testId: "summary-total",
      assert: (el) => expect(el).toHaveTextContent("90 kr"),
    });
    await waitFor(
      () =>
        expect(
          canvas.getByText(
            "Du har redan köpt 1 bild/video. Värdet räknas av från albumpriset – så du betalar bara mellanskillnaden.",
          ),
        ).toBeVisible(),
      {
        timeout: 5000,
      },
    );
  },
};
